// Embedded serif fonts (base64) so the dashboard renders identically whether
// served over HTTP or opened as a single static file, with no external font
// dependency. Both @font-face share the family "Moryn Serif"; the browser picks
// the latin or CJK subset per character via unicode-range.
// - Latin: Source Serif 4 (Adobe, SIL OFL 1.1), variable weight 400-700.
// - CJK: Noto Serif SC (SIL OFL 1.1), weight 400, GB2312 common-character subset.
export const dashboardFontStack =
  '"Moryn Serif", "Source Serif 4", "Noto Serif SC", "Songti SC", Georgia, "Times New Roman", serif';

export function dashboardFontFaceCss(): string {
  return `
    @font-face {
      font-family: "Moryn Serif";
      font-style: normal;
      font-weight: 400 700;
      font-display: swap;
      unicode-range: U+0000-024F, U+2000-206F, U+2C60-2C7F, U+A720-A7FF;
      src: url(data:font/woff2;base64,) format("woff2");
    }
    @font-face {
      font-family: "Moryn Serif";
      font-style: normal;
      font-weight: 400;
      font-display: swap;
      src: url(data:font/woff2;base64,) format("woff2");
    }
  `;
}
